ParamVariationExperiment.BeforeEachExperimentRunCode:
java.io.File probe = new java.io.File(
	System.getProperty( "htx.repo.root", System.getProperty( "user.dir" ) )
).getAbsoluteFile();
while (
	probe != null
	&& !new java.io.File( probe, "config/anylogic_gate_manifest.csv" ).isFile()
) {
	probe = probe.getParentFile();
}
if ( probe == null ) {
	throw new IllegalStateException(
		"Cannot locate repository root from user.dir="
		+ System.getProperty( "user.dir" )
		+ "; set -Dhtx.repo.root=<repository path>"
	);
}
java.io.File outputDirectory = new java.io.File(
	probe,
	"results/raw/anylogic_gate"
).getAbsoluteFile();
gate_output_dir = outputDirectory.getPath();
try {
	java.nio.file.Files.createDirectories( outputDirectory.toPath() );
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_manifest.csv" ).toPath(),
		(
			"schema_version,config_hash,model_version,scenario_id,input_sample_id,"
			+ "replication_id,stream_seed_ids,start_state,arrival_cutoff,drain_end,"
			+ "engine_version\n"
		).getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "entity_log.csv" ).toPath(),
		(
			"schema_version,scenario_id,input_sample_id,replication_id,stream_seed_ids,"
			+ "traveller_id,arrival,security_queue_join,security_start,security_end,"
			+ "immigration_queue_join,immigration_lane,immigration_start,"
			+ "immigration_primary_end,additional_check_flag,additional_check_end,"
			+ "technology_flag,exit,security_resource_id,immigration_resource_id,"
			+ "service_demand\n"
		).getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_summary.csv" ).toPath(),
		(
			"schema_version,scenario_id,input_sample_id,replication_id,stream_seed_ids,"
			+ "arrivals,completed_at_cutoff,wip_at_cutoff,completed_after_drain,"
			+ "security_wait_mean,security_wait_p95,total_wait_mean,total_wait_p95,"
			+ "cutoff_backlog,cohort_clear_time\n"
		).getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException( "Cannot initialise AnyLogic gate outputs", exception );
}

ParamVariationExperiment.BeforeSimulationRunCode:
int replication = getCurrentReplication();
long seed =
	202607270000L
	+ 100L * ( root.input_sample_index + 1L )
	+ (long) replication;
root.replication_id = replication;
root.run_seed = seed;
getEngine().getDefaultRandomGenerator().setSeed( seed );

ParamVariationExperiment.AfterSimulationRunCode:
if (
	root.next_traveller_id != root.gate_entity_count
	|| root.completed_travellers != root.gate_entity_count
) {
	throw new IllegalStateException(
		"Incomplete gate run "
		+ root.input_sample_id
		+ " replication "
		+ root.replication_id
		+ ": arrivals="
		+ root.next_traveller_id
		+ ", completed="
		+ root.completed_travellers
	);
}

java.util.ArrayList<Double> sortedSecurityWaits =
	new java.util.ArrayList<Double>( root.security_waits );
java.util.ArrayList<Double> sortedSystemTimes =
	new java.util.ArrayList<Double>( root.system_times );
java.util.Collections.sort( sortedSecurityWaits );
java.util.Collections.sort( sortedSystemTimes );

double securityWaitSum = 0.0;
for ( double value : sortedSecurityWaits ) {
	securityWaitSum += value;
}
double systemTimeSum = 0.0;
for ( double value : sortedSystemTimes ) {
	systemTimeSum += value;
}
int securityP95Index = Math.max(
	0,
	(int) Math.ceil( 0.95 * sortedSecurityWaits.size() ) - 1
);
int systemP95Index = Math.max(
	0,
	(int) Math.ceil( 0.95 * sortedSystemTimes.size() ) - 1
);
double securityWaitMean = securityWaitSum / sortedSecurityWaits.size();
double securityWaitP95 = sortedSecurityWaits.get( securityP95Index );
double systemTimeMean = systemTimeSum / sortedSystemTimes.size();
double systemTimeP95 = sortedSystemTimes.get( systemP95Index );
int cutoffBacklog = root.gate_entity_count - root.completed_travellers;
String streamSeedIds = "default_rng:" + Long.toString( root.run_seed );

String manifestRow = String.join(
	",",
	new String[] {
		"1.0",
		"285f0694a8512b40b16ca6c61b99f9fb054432233bb98e492856cd9e2be6c91b",
		"gate-v0.1",
		root.scenario_id,
		root.input_sample_id,
		Integer.toString( root.replication_id ),
		streamSeedIds,
		"EMPTY",
		"60.000000000",
		"60.000000000",
		"AnyLogic PLE 8.9.9.202607020720"
	}
) + "\n";
String summaryRow = String.join(
	",",
	new String[] {
		"1.0",
		root.scenario_id,
		root.input_sample_id,
		Integer.toString( root.replication_id ),
		streamSeedIds,
		Integer.toString( root.next_traveller_id ),
		Integer.toString( root.completed_travellers ),
		Integer.toString( cutoffBacklog ),
		Integer.toString( root.completed_travellers ),
		String.format( java.util.Locale.ROOT, "%.9f", securityWaitMean ),
		String.format( java.util.Locale.ROOT, "%.9f", securityWaitP95 ),
		String.format( java.util.Locale.ROOT, "%.9f", systemTimeMean ),
		String.format( java.util.Locale.ROOT, "%.9f", systemTimeP95 ),
		Integer.toString( cutoffBacklog ),
		String.format( java.util.Locale.ROOT, "%.9f", root.last_exit )
	}
) + "\n";
String entityRows = String.join( "\n", root.entity_rows ) + "\n";

try {
	java.nio.file.Files.write(
		new java.io.File( gate_output_dir, "run_manifest.csv" ).toPath(),
		manifestRow.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.APPEND
	);
	java.nio.file.Files.write(
		new java.io.File( gate_output_dir, "entity_log.csv" ).toPath(),
		entityRows.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.APPEND
	);
	java.nio.file.Files.write(
		new java.io.File( gate_output_dir, "run_summary.csv" ).toPath(),
		summaryRow.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.APPEND
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException( "Cannot append AnyLogic gate outputs", exception );
}

SimulationExperiment.BeforeSimulationRunCode:
if (
	!"BASELINE_LOCAL_WINDOW_HPP".equals( root.source_config_id )
	|| !"task1_final_aggregate".equals( root.arrival_evidence_id )
	|| !"LOCAL_WINDOW_HPP_STATIONARY_INDEPENDENT".equals(
		root.arrival_assumption
	)
	|| root.input_sample_id == null
	|| root.input_sample_id.trim().isEmpty()
) {
	throw new IllegalStateException(
		"HPP arrival verification lineage is not frozen"
	);
}
if (
	!Double.isFinite( root.arrival_rate_per_second )
	|| root.arrival_rate_per_second <= 0.0
	|| !Double.isFinite( root.arrival_cutoff_seconds )
	|| root.arrival_cutoff_seconds <= 0.0
	|| root.arrival_seed <= 0L
) {
	throw new IllegalStateException(
		"HPP arrival verification parameters violate the fail-fast domain"
	);
}
double expectedCount =
	root.arrival_rate_per_second * root.arrival_cutoff_seconds;
if (
	root.ple_max_generated_guard <= 0
	|| root.ple_max_generated_guard >= 50000
	|| expectedCount + 10.0 * Math.sqrt( expectedCount )
		>= root.ple_max_generated_guard
) {
	throw new IllegalStateException(
		"HPP arrival guard is unsafe for the configured exposure"
	);
}
getEngine().getDefaultRandomGenerator().setSeed( root.arrival_seed );

SimulationExperiment.AfterSimulationRunCode:
if (
	!root.arrivals_closed
	|| root.guard_hit
	|| root.admitted_at_cutoff != root.arrival_times.size()
	|| root.completed_at_cutoff != root.completed
	|| root.completed != root.arrival_times.size()
	|| root.travellerSource.count() != root.arrival_times.size()
) {
	throw new IllegalStateException(
		"HPP arrival verification failed flow conservation"
	);
}
double previousArrival = -1.0;
for ( double arrivalTime : root.arrival_times ) {
	if (
		!Double.isFinite( arrivalTime )
		|| arrivalTime < 0.0
		|| arrivalTime >= root.arrival_cutoff_seconds
		|| arrivalTime <= previousArrival
	) {
		throw new IllegalStateException(
			"Invalid HPP arrival timestamp: " + arrivalTime
		);
	}
	previousArrival = arrivalTime;
}

double expectedCount =
	root.arrival_rate_per_second * root.arrival_cutoff_seconds;
String manifest =
	"schema_version,experiment_role,readiness_scope,source_config_id,"
	+ "input_sample_id,replication_id,arrival_evidence_id,arrival_assumption,"
	+ "arrival_rate_per_second,arrival_cutoff_seconds,arrival_seed,"
	+ "expected_count,realized_count,guard_limit,guard_hit,engine_version\n"
	+ String.join(
		",",
		new String[] {
			"1.0",
			"DEMAND_MECHANISM_VERIFICATION",
			"ARRIVAL_ONLY",
			root.source_config_id,
			root.input_sample_id,
			"1",
			root.arrival_evidence_id,
			root.arrival_assumption,
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.arrival_rate_per_second
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.arrival_cutoff_seconds
			),
			Long.toString( root.arrival_seed ),
			String.format( java.util.Locale.ROOT, "%.9f", expectedCount ),
			Integer.toString( root.arrival_times.size() ),
			Integer.toString( root.ple_max_generated_guard ),
			Boolean.toString( root.guard_hit ),
			"AnyLogic PLE 8.9.9.202607020720"
		}
	)
	+ "\n";

StringBuilder ledger = new StringBuilder(
	"schema_version,experiment_role,readiness_scope,source_config_id,"
	+ "input_sample_id,replication_id,arrival_seed,sequence,arrival_time\n"
);
for ( int index = 0; index < root.arrival_times.size(); index++ ) {
	ledger.append(
		String.join(
			",",
			new String[] {
				"1.0",
				"DEMAND_MECHANISM_VERIFICATION",
				"ARRIVAL_ONLY",
				root.source_config_id,
				root.input_sample_id,
				"1",
				Long.toString( root.arrival_seed ),
				Integer.toString( index + 1 ),
				String.format(
					java.util.Locale.ROOT,
					"%.9f",
					root.arrival_times.get( index )
				)
			}
		)
	).append( "\n" );
}

String summary =
	"schema_version,experiment_role,readiness_scope,source_config_id,"
	+ "input_sample_id,replication_id,arrival_seed,arrival_rate_per_second,"
	+ "arrival_cutoff_seconds,expected_count,realized_count,"
	+ "source_count,sink_count,guard_hit\n"
	+ String.join(
		",",
		new String[] {
			"1.0",
			"DEMAND_MECHANISM_VERIFICATION",
			"ARRIVAL_ONLY",
			root.source_config_id,
			root.input_sample_id,
			"1",
			Long.toString( root.arrival_seed ),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.arrival_rate_per_second
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.arrival_cutoff_seconds
			),
			String.format( java.util.Locale.ROOT, "%.9f", expectedCount ),
			Integer.toString( root.arrival_times.size() ),
			Long.toString( root.travellerSource.count() ),
			Integer.toString( root.completed ),
			Boolean.toString( root.guard_hit )
		}
	)
	+ "\n";

java.io.File probe = new java.io.File(
	System.getProperty( "htx.repo.root", System.getProperty( "user.dir" ) )
).getAbsoluteFile();
while (
	probe != null
	&& !new java.io.File(
		probe,
		"config/model_run_configs.csv"
	).isFile()
) {
	probe = probe.getParentFile();
}
if ( probe == null ) {
	throw new IllegalStateException(
		"Cannot locate repository root for HPP arrival verification"
	);
}
java.io.File outputDirectory = new java.io.File(
	probe,
	"results/raw/anylogic_hpp_arrival_verification"
).getAbsoluteFile();
try {
	java.nio.file.Files.createDirectories( outputDirectory.toPath() );
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_manifest.csv" ).toPath(),
		manifest.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "arrival_ledger.csv" ).toPath(),
		ledger.toString().getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_summary.csv" ).toPath(),
		summary.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException(
		"Cannot write HPP arrival verification outputs",
		exception
	);
}

SimulationExperiment.BeforeSimulationRunCode:
if ( root.demand_multiplier < 0.5 || root.demand_multiplier > 2.0 )
	throw new IllegalArgumentException(
		"demand_multiplier must be between 0.5 and 2.0"
	);
if ( root.security_capacity < 1 || root.security_capacity > 200
	|| root.immigration_capacity < 1 || root.immigration_capacity > 200 )
	throw new IllegalArgumentException(
		"interactive capacities must be integers between 1 and 200"
	);
if ( root.automation_uptake < 0.0 || root.automation_uptake > 1.0 )
	throw new IllegalArgumentException(
		"automation_uptake must be between 0 and 1"
	);
if ( root.automation_uptake == 0.0 ) {
	root.automation_mapping_mode = "DISABLED";
	root.automation_multiplier = 1.0;
} else {
	if ( !( root.automation_multiplier > 0.0
		&& root.automation_multiplier < 1.0 ) )
		throw new IllegalArgumentException(
			"automation_multiplier must be between 0 and 1 when uptake is positive"
		);
	root.automation_mapping_mode = "MULTIPLIER";
}
root.output_collection_id = "anylogic_operational";
root.config_id = "OP_INTERACTIVE_AD_HOC_V1";
root.scenario_family = "INTERACTIVE_EXPLORATORY";
root.reference_scenario_id = "REFERENCE_ASSUMPTION_SANDBOX_V1";
root.input_sample_id = "LOCAL_WINDOW_HPP_BASE";
root.replication_id = 0;
root.scenario_id = String.format(
	java.util.Locale.ROOT,
	"INTERACTIVE_D%03d_SEC%03d_IMM%03d_U%03d_M%03d",
	(int) Math.round( 100.0 * root.demand_multiplier ),
	root.security_capacity,
	root.immigration_capacity,
	(int) Math.round( 100.0 * root.automation_uptake ),
	(int) Math.round( 100.0 * root.automation_multiplier )
);
String interactiveCanonical = String.format(
	java.util.Locale.ROOT,
	"model=TASK3_OPERATIONAL_POOLED_V1|queue=pooled|"
	+ "demand=%.9f|security_capacity=%d|immigration_capacity=%d|"
	+ "automation_mode=%s|automation_uptake=%.9f|"
	+ "automation_multiplier=%.9f",
	root.demand_multiplier,
	root.security_capacity,
	root.immigration_capacity,
	root.automation_mapping_mode,
	root.automation_uptake,
	root.automation_multiplier
);
try {
	java.security.MessageDigest digest =
		java.security.MessageDigest.getInstance( "SHA-256" );
	byte[] hash = digest.digest(
		interactiveCanonical.getBytes( java.nio.charset.StandardCharsets.UTF_8 )
	);
	StringBuilder hexadecimal = new StringBuilder();
	for ( byte value : hash )
		hexadecimal.append(
			String.format( java.util.Locale.ROOT, "%02x", value & 0xff )
		);
	root.config_sha256 = hexadecimal.toString();
} catch ( java.security.NoSuchAlgorithmException exception ) {
	throw new RuntimeException( "SHA-256 is unavailable", exception );
}
root.presentation_animation_enabled = false;
if ( !"1.0".equals( root.schema_version ) )
	throw new IllegalArgumentException( "schema_version must be 1.0" );
if ( !root.config_sha256.matches( "[0-9a-f]{64}" ) )
	throw new IllegalArgumentException( "config_sha256 must be 64 lowercase hex characters" );
if ( !root.output_collection_id.matches( "[a-z0-9_]+" ) )
	throw new IllegalArgumentException( "output_collection_id is unsafe" );
if ( !"HPP".equals( root.arrival_mode ) )
	throw new IllegalArgumentException( "arrival_mode must be HPP" );
if ( !( root.arrival_rate_per_second > 0.0 ) || !( root.demand_multiplier > 0.0 ) )
	throw new IllegalArgumentException( "arrival rate and demand multiplier must be positive" );
if ( !( root.arrival_cutoff_seconds > 0.0 ) || root.arrival_guard <= 1 )
	throw new IllegalArgumentException( "arrival cutoff and guard are invalid" );
if ( root.arrival_rate_per_second * root.demand_multiplier * root.arrival_cutoff_seconds >= root.arrival_guard )
	throw new IllegalArgumentException( "arrival_guard must exceed expected arrivals" );
if ( !"FULL_DRAIN".equals( root.drain_rule ) )
	throw new IllegalArgumentException( "drain_rule must be FULL_DRAIN" );
if ( root.security_capacity <= 0 || root.immigration_capacity <= 0 )
	throw new IllegalArgumentException( "resource capacities must be positive" );
if ( root.security_queue_capacity <= 0 || root.immigration_queue_capacity <= 0 )
	throw new IllegalArgumentException( "queue capacities must be positive" );
if ( !( root.security_service_p1_seconds > 0.0 )
	|| !( root.immigration_service_p1_seconds > 0.0 ) )
	throw new IllegalArgumentException( "primary service demands must be positive" );
boolean securityServiceContractValid =
	( "FIXED".equals( root.security_service_distribution )
		&& root.security_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.security_service_distribution )
		&& root.security_service_cv > 0.0
		&& root.security_service_cv <= 2.0
		&& Double.isFinite( root.security_service_cv ) );
boolean immigrationServiceContractValid =
	( "FIXED".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv > 0.0
		&& root.immigration_service_cv <= 2.0
		&& Double.isFinite( root.immigration_service_cv ) );
if ( !securityServiceContractValid || !immigrationServiceContractValid )
	throw new IllegalArgumentException(
		"primary service distribution/CV contract is invalid"
	);
if ( "TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version )
	&& ( !"FIXED".equals( root.security_service_distribution )
		|| !"FIXED".equals( root.immigration_service_distribution )
		|| root.security_service_cv != 0.0
		|| root.immigration_service_cv != 0.0 ) )
	throw new IllegalArgumentException(
		"TASK3_OPERATIONAL_POOLED_V1 is frozen to FIXED service and CV=0"
	);
if ( !"pooled".equals( root.queue_policy ) )
	throw new IllegalArgumentException( "v1 implements pooled FCFS only" );
if ( "DISABLED".equals( root.automation_mapping_mode ) ) {
	if ( root.automation_uptake != 0.0 || root.automation_multiplier != 1.0 )
		throw new IllegalArgumentException( "DISABLED automation requires uptake=0 and multiplier=1" );
} else if ( "MULTIPLIER".equals( root.automation_mapping_mode ) ) {
	if ( !( root.automation_uptake > 0.0 && root.automation_uptake <= 1.0 )
		|| !( root.automation_multiplier > 0.0 && root.automation_multiplier < 1.0 ) )
		throw new IllegalArgumentException( "automation inputs are outside their domains" );
} else {
	throw new IllegalArgumentException( "unknown automation_mapping_mode" );
}
if ( "NONE".equals( root.additional_check_semantics ) ) {
	if ( root.additional_check_probability_conventional != 0.0
		|| root.additional_check_probability_technology != 0.0
		|| !"UNSET".equals( root.additional_check_service_distribution )
		|| root.additional_check_service_p1_seconds != 0.0 )
		throw new IllegalArgumentException( "NONE additional-check contract violated" );
} else if ( "COUNTER_HELD_RISK_REFERRAL_PROXY".equals( root.additional_check_semantics ) ) {
	if ( !"FIXED".equals( root.additional_check_service_distribution )
		|| root.additional_check_probability_conventional < 0.0
		|| root.additional_check_probability_conventional > 1.0
		|| root.additional_check_probability_technology < 0.0
		|| root.additional_check_probability_technology > 1.0
		|| !( root.additional_check_service_p1_seconds > 0.0 ) )
		throw new IllegalArgumentException( "risk-proxy inputs are invalid" );
} else {
	throw new IllegalArgumentException( "unknown additional_check_semantics" );
}
if ( !"EMPTY_AND_IDLE".equals( root.start_state )
	|| !"NOT_CALIBRATED".equals( root.calibration_status )
	|| !"COMPARATIVE_WHAT_IF_ONLY".equals( root.claim_ceiling )
	|| !( "NOT_TESTED".equals( root.crn_alignment_status )
		|| "PENDING_VALIDATION".equals( root.crn_alignment_status ) ) )
	throw new IllegalArgumentException( "claim-boundary fields were weakened" );
if ( !"TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version )
	|| root.arrival_rate_per_second != 1.364213
	|| root.arrival_cutoff_seconds != 300.0
	|| root.arrival_guard != 5000
	|| root.security_queue_capacity != 5000
	|| root.security_service_p1_seconds != 21.818181818
	|| root.immigration_queue_capacity != 5000
	|| root.immigration_service_p1_seconds != 13.0
	|| !"pooled".equals( root.queue_policy )
	|| !"NONE".equals( root.additional_check_semantics )
	|| root.additional_check_probability_conventional != 0.0
	|| root.additional_check_probability_technology != 0.0
	|| !"UNSET".equals( root.additional_check_service_distribution )
	|| root.additional_check_service_p1_seconds != 0.0
	|| root.master_seed != 2026072800L
	|| root.arrival_seed != 2026072801L
	|| root.service_seed != 2026072802L
	|| root.routing_seed != 2026072803L
	|| root.tie_seed != 2026072804L )
	throw new IllegalArgumentException(
		"OperationalInteractive permits only the five exposed exploratory inputs; "
		+ "all other mechanism and lineage fields must remain fixed"
	);
getEngine().getDefaultRandomGenerator().setSeed( root.arrival_seed );
root.presentation_animation_enabled = true;

SimulationExperiment.AfterSimulationRunCode:
if ( !"COMPLETE".equals( root.run_status ) )
	throw new IllegalStateException( "operational run did not reach COMPLETE" );
if ( root.guard_hit || root.rejected_or_dropped_count != 0 )
	throw new IllegalStateException( "guard, rejection, or drop detected" );
if ( root.admitted != root.completed )
