	);
	java.nio.file.Files.write(
		runDirectory.resolve( "replication_kpis.csv" ), kpis,
		java.nio.charset.StandardCharsets.UTF_8
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException( "Operational CSV export failed", exception );
}

SimulationExperiment.AfterSimulationRunCode:
if (
	!"VERIFY_TWO_STAGE_A".equals( root.config_id )
	|| !"two_stage_six_person_fixture".equals( root.arrival_fixture_id )
) {
	throw new IllegalStateException(
		"Two-stage verification must use the pinned oracle configuration"
	);
}
if (
	root.max_arrivals < 1
	|| root.arrival_cutoff_seconds < 0.0
	|| root.security_capacity < 1
	|| root.immigration_capacity < 1
	|| root.security_queue_capacity < 1
	|| root.immigration_queue_capacity < 1
	|| root.security_service_p1_seconds <= 0.0
	|| root.immigration_service_p1_seconds <= 0.0
	|| root.oracle_first_arrival_seconds < 0.0
	|| root.oracle_early_interarrival_seconds <= 0.0
	|| root.oracle_late_interarrival_seconds <= 0.0
	|| root.oracle_interval_switch_after < 1
	|| root.oracle_interval_switch_after >= root.max_arrivals
) {
	throw new IllegalStateException(
		"Two-stage verification parameters violate the fail-fast domain"
	);
}
if (
	root.admitted != root.max_arrivals
	|| root.completed != root.max_arrivals
) {
	throw new IllegalStateException(
		"Two-stage verification expected "
		+ root.max_arrivals
		+ " admitted/completed; admitted="
		+ root.admitted
		+ ", completed="
		+ root.completed
	);
}
if (
	root.security_queue_count != 0
	|| root.security_in_service_count != 0
	|| root.immigration_queue_count != 0
	|| root.immigration_in_service_count != 0
) {
	throw new IllegalStateException( "Two-stage verification did not drain" );
}
if (
	root.completed_at_cutoff != 1
	|| root.security_queue_at_cutoff != 2
	|| root.security_in_service_at_cutoff != 1
	|| root.immigration_queue_at_cutoff != 1
	|| root.immigration_in_service_at_cutoff != 1
) {
	throw new IllegalStateException(
		"Unexpected cutoff state: completed="
		+ root.completed_at_cutoff
		+ ", security_queue="
		+ root.security_queue_at_cutoff
		+ ", security_in_service="
		+ root.security_in_service_at_cutoff
		+ ", immigration_queue="
		+ root.immigration_queue_at_cutoff
		+ ", immigration_in_service="
		+ root.immigration_in_service_at_cutoff
	);
}
if ( Math.abs( root.last_exit - 20.0 ) > 1e-9 ) {
	throw new IllegalStateException(
		"Expected drain end 20.0, found " + root.last_exit
	);
}
if ( root.entity_rows.size() != root.max_arrivals ) {
	throw new IllegalStateException(
		"Expected "
		+ root.max_arrivals
		+ " entity rows, found "
		+ root.entity_rows.size()
	);
}

java.util.ArrayList<Double> securityWaits =
	new java.util.ArrayList<Double>( root.security_waits );
java.util.ArrayList<Double> immigrationWaits =
	new java.util.ArrayList<Double>( root.immigration_waits );
java.util.ArrayList<Double> totalQueueWaits =
	new java.util.ArrayList<Double>( root.total_queue_waits );
java.util.ArrayList<Double> systemTimes =
	new java.util.ArrayList<Double>( root.system_times );
java.util.Collections.sort( securityWaits );
java.util.Collections.sort( immigrationWaits );
java.util.Collections.sort( totalQueueWaits );
java.util.Collections.sort( systemTimes );

double securityWaitSum = 0.0;
for ( double value : securityWaits ) {
	securityWaitSum += value;
}
double immigrationWaitSum = 0.0;
for ( double value : immigrationWaits ) {
	immigrationWaitSum += value;
}
double totalQueueWaitSum = 0.0;
for ( double value : totalQueueWaits ) {
	totalQueueWaitSum += value;
}
double systemTimeSum = 0.0;
for ( double value : systemTimes ) {
	systemTimeSum += value;
}
int p95Index = Math.max(
	0,
	(int) Math.ceil( 0.95 * securityWaits.size() ) - 1
);

String manifest =
	"schema_version,verification_contract_hash,model_version,experiment_role,"
	+ "scenario_id,input_sample_id,replication_id,stream_seed_ids,start_state,"
	+ "arrival_cutoff,drain_end,engine_version\n"
	+ String.join(
		",",
		new String[] {
			"1.0",
			"daf13e43beb453b10855dd69ecbeeef65e05afbaf75da070052ddfca1cf58dcb",
			"two-stage-verification-v0.1",
			"SYNTHETIC_MECHANISM_VERIFICATION",
			root.scenario_id,
			root.input_sample_id,
			Integer.toString( root.replication_id ),
			"fixed_oracle:2026072709",
			"EMPTY",
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.arrival_cutoff_seconds
			),
			String.format( java.util.Locale.ROOT, "%.9f", root.last_exit ),
			"AnyLogic PLE 8.9.9.202607020720"
		}
	)
	+ "\n";

String entityHeader =
	"schema_version,experiment_role,scenario_id,input_sample_id,replication_id,"
	+ "stream_seed_ids,traveller_id,arrival,security_queue_join,security_start,"
	+ "security_end,immigration_queue_join,immigration_lane,immigration_start,"
	+ "immigration_primary_end,additional_check_flag,additional_check_end,"
	+ "technology_flag,exit,security_resource_id,immigration_resource_id,"
	+ "security_service_demand,immigration_service_demand\n";
String entityLog = entityHeader + String.join( "\n", root.entity_rows ) + "\n";

int wipAtCutoff =
	root.security_queue_at_cutoff
	+ root.security_in_service_at_cutoff
	+ root.immigration_queue_at_cutoff
	+ root.immigration_in_service_at_cutoff;
String summary =
	"schema_version,experiment_role,scenario_id,input_sample_id,replication_id,"
	+ "stream_seed_ids,arrivals,completed_at_cutoff,security_queue_at_cutoff,"
	+ "security_in_service_at_cutoff,immigration_queue_at_cutoff,"
	+ "immigration_in_service_at_cutoff,wip_at_cutoff,completed_after_drain,"
	+ "security_wait_mean,security_wait_p95,immigration_wait_mean,"
	+ "immigration_wait_p95,total_queue_wait_mean,total_queue_wait_p95,"
	+ "system_time_mean,system_time_p95,cutoff_backlog,"
	+ "cohort_clear_time_after_cutoff\n"
	+ String.join(
		",",
		new String[] {
			"1.0",
			"SYNTHETIC_MECHANISM_VERIFICATION",
			root.scenario_id,
			root.input_sample_id,
			Integer.toString( root.replication_id ),
			"fixed_oracle:2026072709",
			Integer.toString( root.admitted ),
			Integer.toString( root.completed_at_cutoff ),
			Integer.toString( root.security_queue_at_cutoff ),
			Integer.toString( root.security_in_service_at_cutoff ),
			Integer.toString( root.immigration_queue_at_cutoff ),
			Integer.toString( root.immigration_in_service_at_cutoff ),
			Integer.toString( wipAtCutoff ),
			Integer.toString( root.completed ),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				securityWaitSum / securityWaits.size()
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				securityWaits.get( p95Index )
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				immigrationWaitSum / immigrationWaits.size()
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				immigrationWaits.get( p95Index )
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				totalQueueWaitSum / totalQueueWaits.size()
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				totalQueueWaits.get( p95Index )
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				systemTimeSum / systemTimes.size()
			),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				systemTimes.get( p95Index )
			),
			Integer.toString( root.admitted - root.completed_at_cutoff ),
			String.format(
				java.util.Locale.ROOT,
				"%.9f",
				root.last_exit - root.arrival_cutoff_seconds
			)
		}
	)
	+ "\n";

java.io.File probe = new java.io.File(
	System.getProperty( "htx.repo.root", System.getProperty( "user.dir" ) )
).getAbsoluteFile();
while (
	probe != null
	&& !new java.io.File( probe, "config/anylogic_gate_manifest.csv" ).isFile()
) {
	probe = probe.getParentFile();
}
if ( probe == null ) {
	throw new IllegalStateException(
		"Cannot locate repository root for two-stage verification"
	);
}
java.io.File outputDirectory = new java.io.File(
	probe,
	"results/raw/anylogic_two_stage_verification"
).getAbsoluteFile();
try {
	java.nio.file.Files.createDirectories( outputDirectory.toPath() );
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_manifest.csv" ).toPath(),
		manifest.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "entity_log.csv" ).toPath(),
		entityLog.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
	java.nio.file.Files.write(
		new java.io.File( outputDirectory, "run_summary.csv" ).toPath(),
		summary.getBytes( java.nio.charset.StandardCharsets.UTF_8 ),
		java.nio.file.StandardOpenOption.CREATE,
		java.nio.file.StandardOpenOption.TRUNCATE_EXISTING,
		java.nio.file.StandardOpenOption.WRITE
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException(
		"Cannot write two-stage verification outputs",
		exception
	);
}

ParamVariationExperiment.BeforeSimulationRunCode:
root.presentation_animation_enabled = false;
if ( !"1.0".equals( root.schema_version ) )
	throw new IllegalArgumentException( "schema_version must be 1.0" );
if ( !root.config_sha256.matches( "[0-9a-f]{64}" ) )
	throw new IllegalArgumentException( "config_sha256 must be 64 lowercase hex characters" );
if ( !root.output_collection_id.matches( "[a-z0-9_]+" ) )
	throw new IllegalArgumentException( "output_collection_id is unsafe" );
if ( !"HPP".equals( root.arrival_mode ) )
	throw new IllegalArgumentException( "arrival_mode must be HPP" );
if ( !( root.arrival_rate_per_second > 0.0 ) || !( root.demand_multiplier > 0.0 ) )
	throw new IllegalArgumentException( "arrival rate and demand multiplier must be positive" );
if ( !( root.arrival_cutoff_seconds > 0.0 ) || root.arrival_guard <= 1 )
	throw new IllegalArgumentException( "arrival cutoff and guard are invalid" );
if ( root.arrival_rate_per_second * root.demand_multiplier * root.arrival_cutoff_seconds >= root.arrival_guard )
	throw new IllegalArgumentException( "arrival_guard must exceed expected arrivals" );
if ( !"FULL_DRAIN".equals( root.drain_rule ) )
	throw new IllegalArgumentException( "drain_rule must be FULL_DRAIN" );
if ( root.security_capacity <= 0 || root.immigration_capacity <= 0 )
	throw new IllegalArgumentException( "resource capacities must be positive" );
if ( root.security_queue_capacity <= 0 || root.immigration_queue_capacity <= 0 )
	throw new IllegalArgumentException( "queue capacities must be positive" );
if ( !( root.security_service_p1_seconds > 0.0 )
	|| !( root.immigration_service_p1_seconds > 0.0 ) )
	throw new IllegalArgumentException( "primary service demands must be positive" );
boolean securityServiceContractValid =
	( "FIXED".equals( root.security_service_distribution )
		&& root.security_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.security_service_distribution )
		&& root.security_service_cv > 0.0
		&& root.security_service_cv <= 2.0
		&& Double.isFinite( root.security_service_cv ) );
boolean immigrationServiceContractValid =
	( "FIXED".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv > 0.0
		&& root.immigration_service_cv <= 2.0
		&& Double.isFinite( root.immigration_service_cv ) );
if ( !securityServiceContractValid || !immigrationServiceContractValid )
	throw new IllegalArgumentException(
		"primary service distribution/CV contract is invalid"
	);
if ( "TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version )
	&& ( !"FIXED".equals( root.security_service_distribution )
		|| !"FIXED".equals( root.immigration_service_distribution )
		|| root.security_service_cv != 0.0
		|| root.immigration_service_cv != 0.0 ) )
	throw new IllegalArgumentException(
		"TASK3_OPERATIONAL_POOLED_V1 is frozen to FIXED service and CV=0"
	);
if ( !"pooled".equals( root.queue_policy ) )
	throw new IllegalArgumentException( "v1 implements pooled FCFS only" );
if ( "DISABLED".equals( root.automation_mapping_mode ) ) {
	if ( root.automation_uptake != 0.0 || root.automation_multiplier != 1.0 )
		throw new IllegalArgumentException( "DISABLED automation requires uptake=0 and multiplier=1" );
} else if ( "MULTIPLIER".equals( root.automation_mapping_mode ) ) {
	if ( !( root.automation_uptake > 0.0 && root.automation_uptake <= 1.0 )
		|| !( root.automation_multiplier > 0.0 && root.automation_multiplier < 1.0 ) )
		throw new IllegalArgumentException( "automation inputs are outside their domains" );
} else {
	throw new IllegalArgumentException( "unknown automation_mapping_mode" );
}
if ( "NONE".equals( root.additional_check_semantics ) ) {
	if ( root.additional_check_probability_conventional != 0.0
		|| root.additional_check_probability_technology != 0.0
		|| !"UNSET".equals( root.additional_check_service_distribution )
		|| root.additional_check_service_p1_seconds != 0.0 )
		throw new IllegalArgumentException( "NONE additional-check contract violated" );
} else if ( "COUNTER_HELD_RISK_REFERRAL_PROXY".equals( root.additional_check_semantics ) ) {
	if ( !"FIXED".equals( root.additional_check_service_distribution )
		|| root.additional_check_probability_conventional < 0.0
		|| root.additional_check_probability_conventional > 1.0
		|| root.additional_check_probability_technology < 0.0
		|| root.additional_check_probability_technology > 1.0
		|| !( root.additional_check_service_p1_seconds > 0.0 ) )
		throw new IllegalArgumentException( "risk-proxy inputs are invalid" );
} else {
	throw new IllegalArgumentException( "unknown additional_check_semantics" );
}
if ( !"EMPTY_AND_IDLE".equals( root.start_state )
	|| !"NOT_CALIBRATED".equals( root.calibration_status )
	|| !"COMPARATIVE_WHAT_IF_ONLY".equals( root.claim_ceiling )
	|| !( "NOT_TESTED".equals( root.crn_alignment_status )
		|| "PENDING_VALIDATION".equals( root.crn_alignment_status ) ) )
	throw new IllegalArgumentException( "claim-boundary fields were weakened" );
if ( !"TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version ) )
	throw new IllegalArgumentException(
		"CapacityRobustnessConfirmatory model_version mismatch"
	);
if ( !"confirmatory_capacity".equals( root.output_collection_id ) )
	throw new IllegalArgumentException(
		"CapacityRobustnessConfirmatory output collection mismatch"
	);
if ( root.master_seed != 202607290000L )
	throw new IllegalArgumentException(
		"CapacityRobustnessConfirmatory master seed mismatch"
	);
String expectedConfigId = null;
String expectedConfigHash = null;
if ( "REFERENCE_ASSUMPTION_SANDBOX_V1".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_EXACT95_LOW_REFERENCE_ASSUMPTION_SANDBOX_V1";
	expectedConfigHash = "32b9044b5bbd75968a07e8c7fc390d8c3419cadcce37bf0965896dd768445e2b";
}
else if ( "CAPACITY_SECURITY_PLUS_4".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_EXACT95_LOW_CAPACITY_SECURITY_PLUS_4";
	expectedConfigHash = "a74f1c43d1e7330dabf9ae37612321af21799b456bd27f56db170446d229217d";
}
else if ( "CAPACITY_IMMIGRATION_PLUS_3".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_EXACT95_LOW_CAPACITY_IMMIGRATION_PLUS_3";
	expectedConfigHash = "d154b0dba54f481e612a360ff3e08fee334b279d1c08b2168c3ce51b4a1313bc";
}
else if ( "CAPACITY_BOTH_PLUS".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_EXACT95_LOW_CAPACITY_BOTH_PLUS";
	expectedConfigHash = "45f53fc3706fbd4413cadc5030b851fb533d4189450a73803837ccdf0a203f22";
}
else if ( "REFERENCE_ASSUMPTION_SANDBOX_V1".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_BASE".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_MLE_BASE_REFERENCE_ASSUMPTION_SANDBOX_V1";
	expectedConfigHash = "369372d7e06066baf12416f63c9b12a0af11b1ef17459431e126a703ba4c7eae";
}
else if ( "CAPACITY_SECURITY_PLUS_4".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_BASE".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_MLE_BASE_CAPACITY_SECURITY_PLUS_4";
	expectedConfigHash = "0efc30229024df398b0a79670c550ea3869c5337e3f66926aa0fac683945864d";
}
else if ( "CAPACITY_IMMIGRATION_PLUS_3".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_BASE".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_CONFIRM_MLE_BASE_CAPACITY_IMMIGRATION_PLUS_3";
	expectedConfigHash = "52e5a50942acb0714e5eb93930edb571a9de4facb82099f63da0ea7457690a70";
}
else if ( "CAPACITY_BOTH_PLUS".equals( root.scenario_id )
