ParamVariationExperiment.AfterSimulationRunCode:
if ( !"COMPLETE".equals( root.run_status ) )
	throw new IllegalStateException( "operational run did not reach COMPLETE" );
if ( root.guard_hit || root.rejected_or_dropped_count != 0 )
	throw new IllegalStateException( "guard, rejection, or drop detected" );
if ( root.admitted != root.completed )
	throw new IllegalStateException( "full-drain conservation failed" );
if ( root.security_queue_count != 0 || root.security_in_service_count != 0
	|| root.immigration_queue_count != 0 || root.immigration_in_service_count != 0 )
	throw new IllegalStateException( "non-zero WIP after drain" );
int wipAtCutoff =
	root.security_queue_at_cutoff + root.security_in_service_at_cutoff
	+ root.immigration_queue_at_cutoff + root.immigration_in_service_at_cutoff;
boolean conservationPass =
	root.admitted_at_cutoff == root.completed_at_cutoff + wipAtCutoff;
if ( !conservationPass )
	throw new IllegalStateException( "cutoff conservation failed" );

java.util.ArrayList<Double> securitySorted =
	new java.util.ArrayList<Double>( root.security_waits );
java.util.ArrayList<Double> immigrationSorted =
	new java.util.ArrayList<Double>( root.immigration_waits );
java.util.ArrayList<Double> totalSorted =
	new java.util.ArrayList<Double>( root.total_queue_waits );
java.util.ArrayList<Double> systemSorted =
	new java.util.ArrayList<Double>( root.system_times );
java.util.Collections.sort( securitySorted );
java.util.Collections.sort( immigrationSorted );
java.util.Collections.sort( totalSorted );
java.util.Collections.sort( systemSorted );
double securitySum = 0.0, immigrationSum = 0.0, totalSum = 0.0, systemSum = 0.0;
for ( double value : securitySorted ) securitySum += value;
for ( double value : immigrationSorted ) immigrationSum += value;
for ( double value : totalSorted ) totalSum += value;
for ( double value : systemSorted ) systemSum += value;
int n = root.completed;
if ( n <= 0 ) throw new IllegalStateException( "operational run generated no travellers" );
int p95Index = Math.max( 0, (int) Math.ceil( 0.95 * n ) - 1 );
double drainEnd = Math.max( root.arrival_cutoff_seconds, root.last_exit );
int cutoffBacklog = root.admitted_at_cutoff - root.completed_at_cutoff;
double securityUtilization =
	root.security_busy_seconds / ( root.security_capacity * drainEnd );
double immigrationUtilization =
	root.immigration_busy_seconds / ( root.immigration_capacity * drainEnd );
java.util.function.DoubleFunction<String> number = value ->
	String.format( java.util.Locale.ROOT, "%.9f", value );

java.io.File probe = new java.io.File(
	System.getProperty( "htx.repo.root", System.getProperty( "user.dir" ) )
).getAbsoluteFile();
while ( probe != null
	&& !new java.io.File( probe, "config/operational_scenarios.csv" ).isFile() ) {
	probe = probe.getParentFile();
}
if ( probe == null )
	throw new IllegalStateException( "Cannot locate repository root" );
java.nio.file.Path runDirectory = new java.io.File(
	probe,
	String.format(
		java.util.Locale.ROOT,
		"results/raw/%s/%s/%s/replication_%03d",
		root.output_collection_id,
		root.scenario_id,
		root.input_sample_id,
		root.replication_id
	)
).toPath();
try {
	java.nio.file.Files.createDirectories( runDirectory );
	java.util.ArrayList<String> manifest = new java.util.ArrayList<String>();
	manifest.add(
		"schema_version,config_id,config_sha256,model_version,scenario_id,"
		+ "scenario_family,reference_scenario_id,input_sample_id,replication_id,"
		+ "master_seed,arrival_seed,service_seed,routing_seed,tie_seed,start_state,"
		+ "arrival_mode,arrival_cutoff_seconds,drain_end_seconds,drain_rule,"
		+ "engine_name,engine_version,calibration_status,claim_ceiling,"
		+ "crn_alignment_status,run_status"
	);
	manifest.add( String.join( ",", new String[] {
		root.schema_version, root.config_id, root.config_sha256, root.model_version,
		root.scenario_id, root.scenario_family, root.reference_scenario_id,
		root.input_sample_id, Integer.toString( root.replication_id ),
		Long.toString( root.master_seed ), Long.toString( root.arrival_seed ),
		Long.toString( root.service_seed ), Long.toString( root.routing_seed ),
		Long.toString( root.tie_seed ), root.start_state, root.arrival_mode,
		number.apply( root.arrival_cutoff_seconds ), number.apply( drainEnd ),
		root.drain_rule, "AnyLogic", "8.9.9.202607020720",
		root.calibration_status, root.claim_ceiling, root.crn_alignment_status,
		root.run_status
	} ) );
	java.util.ArrayList<String> entities = new java.util.ArrayList<String>();
	entities.add(
		"schema_version,config_id,config_sha256,model_version,scenario_id,"
		+ "input_sample_id,replication_id,traveller_id,arrival_seconds,"
		+ "security_service_demand_seconds,"
		+ "immigration_conventional_service_demand_seconds,automation_u,"
		+ "additional_check_u,lane_tie_u,security_queue_join_seconds,"
		+ "security_start_seconds,security_end_seconds,"
		+ "immigration_queue_join_seconds,immigration_lane_id,"
		+ "immigration_start_seconds,technology_flag,"
		+ "immigration_primary_service_demand_seconds,"
		+ "immigration_primary_end_seconds,additional_check_flag,"
		+ "additional_check_service_demand_seconds,"
		+ "additional_check_end_seconds,exit_seconds,security_resource_id,"
		+ "immigration_resource_id"
	);
	entities.addAll( root.entity_log_rows );
	java.util.ArrayList<String> kpis = new java.util.ArrayList<String>();
	kpis.add(
		"schema_version,config_id,config_sha256,model_version,scenario_id,"
		+ "input_sample_id,replication_id,arrival_cutoff_seconds,"
		+ "drain_end_seconds,arrivals,completed_at_cutoff,"
		+ "security_queue_at_cutoff,security_in_service_at_cutoff,"
		+ "immigration_queue_at_cutoff,immigration_in_service_at_cutoff,"
		+ "wip_at_cutoff,completed_after_drain,rejected_or_dropped_count,"
		+ "technology_count,additional_check_count,"
		+ "security_wait_mean_seconds,security_wait_p95_seconds,"
		+ "immigration_wait_mean_seconds,immigration_wait_p95_seconds,"
		+ "total_queue_wait_mean_seconds,total_queue_wait_p95_seconds,"
		+ "total_queue_wait_exceed_600_rate,total_queue_wait_exceed_900_rate,"
		+ "total_queue_wait_exceed_1200_rate,system_time_mean_seconds,"
		+ "system_time_p95_seconds,security_utilization,immigration_utilization,"
		+ "cutoff_backlog,cutoff_backlog_fraction,"
		+ "cohort_clear_time_after_cutoff_seconds,conservation_pass,run_status"
	);
	kpis.add( String.join( ",", new String[] {
		root.schema_version, root.config_id, root.config_sha256, root.model_version,
		root.scenario_id, root.input_sample_id, Integer.toString( root.replication_id ),
		number.apply( root.arrival_cutoff_seconds ), number.apply( drainEnd ),
		Integer.toString( root.admitted ), Integer.toString( root.completed_at_cutoff ),
		Integer.toString( root.security_queue_at_cutoff ),
		Integer.toString( root.security_in_service_at_cutoff ),
		Integer.toString( root.immigration_queue_at_cutoff ),
		Integer.toString( root.immigration_in_service_at_cutoff ),
		Integer.toString( wipAtCutoff ), Integer.toString( root.completed ),
		Integer.toString( root.rejected_or_dropped_count ),
		Integer.toString( root.technology_count ),
		Integer.toString( root.additional_check_count ),
		number.apply( securitySum / n ), number.apply( securitySorted.get( p95Index ) ),
		number.apply( immigrationSum / n ), number.apply( immigrationSorted.get( p95Index ) ),
		number.apply( totalSum / n ), number.apply( totalSorted.get( p95Index ) ),
		number.apply( (double) root.exceed_600_count / n ),
		number.apply( (double) root.exceed_900_count / n ),
		number.apply( (double) root.exceed_1200_count / n ),
		number.apply( systemSum / n ), number.apply( systemSorted.get( p95Index ) ),
		number.apply( securityUtilization ), number.apply( immigrationUtilization ),
		Integer.toString( cutoffBacklog ),
		number.apply( root.admitted_at_cutoff > 0
			? (double) cutoffBacklog / root.admitted_at_cutoff : 0.0 ),
		number.apply( Math.max( 0.0, drainEnd - root.arrival_cutoff_seconds ) ),
		Boolean.toString( conservationPass ), root.run_status
	} ) );
	java.nio.file.Files.write(
		runDirectory.resolve( "run_manifest.csv" ), manifest,
		java.nio.charset.StandardCharsets.UTF_8
	);
	java.nio.file.Files.write(
		runDirectory.resolve( "entity_log.csv" ), entities,
		java.nio.charset.StandardCharsets.UTF_8
	);
	java.nio.file.Files.write(
		runDirectory.resolve( "replication_kpis.csv" ), kpis,
		java.nio.charset.StandardCharsets.UTF_8
	);
} catch ( java.io.IOException exception ) {
	throw new RuntimeException( "Operational CSV export failed", exception );
}

ParamVariationExperiment.BeforeSimulationRunCode:
root.presentation_animation_enabled = false;
if ( !"1.0".equals( root.schema_version ) )
	throw new IllegalArgumentException( "schema_version must be 1.0" );
if ( !root.config_sha256.matches( "[0-9a-f]{64}" ) )
	throw new IllegalArgumentException( "config_sha256 must be 64 lowercase hex characters" );
if ( !root.output_collection_id.matches( "[a-z0-9_]+" ) )
	throw new IllegalArgumentException( "output_collection_id is unsafe" );
if ( !"HPP".equals( root.arrival_mode ) )
	throw new IllegalArgumentException( "arrival_mode must be HPP" );
if ( !( root.arrival_rate_per_second > 0.0 ) || !( root.demand_multiplier > 0.0 ) )
	throw new IllegalArgumentException( "arrival rate and demand multiplier must be positive" );
if ( !( root.arrival_cutoff_seconds > 0.0 ) || root.arrival_guard <= 1 )
	throw new IllegalArgumentException( "arrival cutoff and guard are invalid" );
if ( root.arrival_rate_per_second * root.demand_multiplier * root.arrival_cutoff_seconds >= root.arrival_guard )
	throw new IllegalArgumentException( "arrival_guard must exceed expected arrivals" );
if ( !"FULL_DRAIN".equals( root.drain_rule ) )
	throw new IllegalArgumentException( "drain_rule must be FULL_DRAIN" );
if ( root.security_capacity <= 0 || root.immigration_capacity <= 0 )
	throw new IllegalArgumentException( "resource capacities must be positive" );
if ( root.security_queue_capacity <= 0 || root.immigration_queue_capacity <= 0 )
	throw new IllegalArgumentException( "queue capacities must be positive" );
if ( !( root.security_service_p1_seconds > 0.0 )
	|| !( root.immigration_service_p1_seconds > 0.0 ) )
	throw new IllegalArgumentException( "primary service demands must be positive" );
boolean securityServiceContractValid =
	( "FIXED".equals( root.security_service_distribution )
		&& root.security_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.security_service_distribution )
		&& root.security_service_cv > 0.0
		&& root.security_service_cv <= 2.0
		&& Double.isFinite( root.security_service_cv ) );
boolean immigrationServiceContractValid =
	( "FIXED".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv == 0.0 )
	|| ( "LOGNORMAL_MEAN_CV".equals( root.immigration_service_distribution )
		&& root.immigration_service_cv > 0.0
		&& root.immigration_service_cv <= 2.0
		&& Double.isFinite( root.immigration_service_cv ) );
if ( !securityServiceContractValid || !immigrationServiceContractValid )
	throw new IllegalArgumentException(
		"primary service distribution/CV contract is invalid"
	);
if ( "TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version )
	&& ( !"FIXED".equals( root.security_service_distribution )
		|| !"FIXED".equals( root.immigration_service_distribution )
		|| root.security_service_cv != 0.0
		|| root.immigration_service_cv != 0.0 ) )
	throw new IllegalArgumentException(
		"TASK3_OPERATIONAL_POOLED_V1 is frozen to FIXED service and CV=0"
	);
if ( !"pooled".equals( root.queue_policy ) )
	throw new IllegalArgumentException( "v1 implements pooled FCFS only" );
if ( "DISABLED".equals( root.automation_mapping_mode ) ) {
	if ( root.automation_uptake != 0.0 || root.automation_multiplier != 1.0 )
		throw new IllegalArgumentException( "DISABLED automation requires uptake=0 and multiplier=1" );
} else if ( "MULTIPLIER".equals( root.automation_mapping_mode ) ) {
	if ( !( root.automation_uptake > 0.0 && root.automation_uptake <= 1.0 )
		|| !( root.automation_multiplier > 0.0 && root.automation_multiplier < 1.0 ) )
		throw new IllegalArgumentException( "automation inputs are outside their domains" );
} else {
	throw new IllegalArgumentException( "unknown automation_mapping_mode" );
}
if ( "NONE".equals( root.additional_check_semantics ) ) {
	if ( root.additional_check_probability_conventional != 0.0
		|| root.additional_check_probability_technology != 0.0
		|| !"UNSET".equals( root.additional_check_service_distribution )
		|| root.additional_check_service_p1_seconds != 0.0 )
		throw new IllegalArgumentException( "NONE additional-check contract violated" );
} else if ( "COUNTER_HELD_RISK_REFERRAL_PROXY".equals( root.additional_check_semantics ) ) {
	if ( !"FIXED".equals( root.additional_check_service_distribution )
		|| root.additional_check_probability_conventional < 0.0
		|| root.additional_check_probability_conventional > 1.0
		|| root.additional_check_probability_technology < 0.0
		|| root.additional_check_probability_technology > 1.0
		|| !( root.additional_check_service_p1_seconds > 0.0 ) )
		throw new IllegalArgumentException( "risk-proxy inputs are invalid" );
} else {
	throw new IllegalArgumentException( "unknown additional_check_semantics" );
}
if ( !"EMPTY_AND_IDLE".equals( root.start_state )
	|| !"NOT_CALIBRATED".equals( root.calibration_status )
	|| !"COMPARATIVE_WHAT_IF_ONLY".equals( root.claim_ceiling )
	|| !( "NOT_TESTED".equals( root.crn_alignment_status )
		|| "PENDING_VALIDATION".equals( root.crn_alignment_status ) ) )
	throw new IllegalArgumentException( "claim-boundary fields were weakened" );
if ( !"TASK3_OPERATIONAL_POOLED_V1".equals( root.model_version ) )
	throw new IllegalArgumentException(
		"CapacityAvailabilityStress model_version mismatch"
	);
if ( !"capacity_availability".equals( root.output_collection_id ) )
	throw new IllegalArgumentException(
		"CapacityAvailabilityStress output collection mismatch"
	);
if ( root.master_seed != 202607290000L )
	throw new IllegalArgumentException(
		"CapacityAvailabilityStress master seed mismatch"
	);
String expectedConfigId = null;
String expectedConfigHash = null;
if ( "CAPACITY_AVAIL_SECURITY_MINUS_4".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_AVAIL_EXACT95_LOW_CAPACITY_AVAIL_SECURITY_MINUS_4";
	expectedConfigHash = "1f8092810bbef01772ff3ebb85a2552e0d06505aad1d15e7efe3bd284da3ac20";
}
else if ( "CAPACITY_AVAIL_IMMIGRATION_MINUS_3".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_AVAIL_EXACT95_LOW_CAPACITY_AVAIL_IMMIGRATION_MINUS_3";
	expectedConfigHash = "adddb2957e2ff950388b3585d73083e35714c7580c83d613a5983ffb1effca18";
}
else if ( "CAPACITY_AVAIL_JOINT_MINUS_4_MINUS_3".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_AVAIL_EXACT95_LOW_CAPACITY_AVAIL_JOINT_MINUS_4_MINUS_3";
	expectedConfigHash = "56b5c732766e7dd4952e1300365fcd02ef95a48a8e68991d791c227fc21e1360";
}
else if ( "CAPACITY_AVAIL_SEVERE_JOINT_30_17".equals( root.scenario_id )
	&& "LOCAL_WINDOW_HPP_EXACT95_LOW".equals( root.input_sample_id ) ) {
	expectedConfigId = "OP_AVAIL_EXACT95_LOW_CAPACITY_AVAIL_SEVERE_JOINT_30_17";
	expectedConfigHash = "81780aaca4c91f52a7bd742048fa471e5f30c577c67881ba50fbd8b7f3cfb3f3";
}
else if ( "CAPACITY_AVAIL_SECURITY_MINUS_4".equals( root.scenario_id )
